$parseMoney = static function($raw) {
 $value=trim(str_replace(array('R$'," ","\xc2\xa0"),'',(string)$raw));
 if(preg_match('/^(?:\d{1,3}(?:\.\d{3})+|\d+),\d{1,2}$/',$value)) $value=str_replace(',', '.', str_replace('.', '', $value));
 elseif(preg_match('/^\d{1,3}(?:\.\d{3})+$/',$value)) $value=str_replace('.', '', $value);
 elseif(preg_match('/^\d+(?:[.,]\d{1,2})?$/',$value)) $value=str_replace(',', '.', $value);
 else throw new RuntimeException('Informe um valor válido, por exemplo 1.234,56.');
 $parts=explode('.', $value, 2); $whole=ltrim($parts[0], '0'); if($whole==='')$whole='0';
 if(strlen($whole)>10) throw new RuntimeException('O valor excede o limite permitido.');
 $decimal=isset($parts[1])?str_pad($parts[1],2,'0'): '00';
 $normalized=$whole.'.'.$decimal;
 if((float)$normalized<=0) throw new RuntimeException('O valor deve ser maior que zero.');
 return $normalized;
};
$validDate = static function($value) {
 if(!is_string($value)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$value)) return false;
 $date=DateTimeImmutable::createFromFormat('!Y-m-d',$value); $issues=DateTimeImmutable::getLastErrors();
 return $date!==false && ($issues===false || ($issues['warning_count']===0 && $issues['error_count']===0)) && $date->format('Y-m-d')===$value;
};
