$sum->execute([$uid,$start,$end]); $tot=['income'=>0,'expense'=>0,'pending'=>0]; foreach($sum as $r){if($r['status']==='pending')$tot['pending']+=(float)$r['total']; elseif($r['kind']==='income')$tot['income']+=(float)$r['total'];else $tot['expense']+=(float)$r['total'];}
$cats=$pdo->prepare("SELECT c.id,c.name,c.kind,c.color FROM fin_categories c WHERE c.user_id IS NULL OR c.user_id=? ORDER BY c.name"); $cats->execute([$uid]); $categories=$cats->fetchAll();
$accounts=$pdo->prepare('SELECT id,name FROM fin_accounts WHERE user_id=? ORDER BY name'); $accounts->execute([$uid]); $accounts=$accounts->fetchAll();
$accountBalances=$pdo->prepare("SELECT a.id,a.name,a.opening_balance,COALESCE(SUM(CASE WHEN t.status='paid' AND t.kind='income' THEN t.amount WHEN t.status='paid' AND t.kind='expense' THEN -t.amount ELSE 0 END),0) AS movement FROM fin_accounts a LEFT JOIN fin_transactions t ON t.account_id=a.id AND t.user_id=a.user_id WHERE a.user_id=? GROUP BY a.id,a.name,a.opening_balance ORDER BY a.name"); $accountBalances->execute([$uid]); $accountBalances=$accountBalances->fetchAll(); $allBalance=0; foreach($accountBalances as $ab){$allBalance+=(float)$ab['opening_balance']+(float)$ab['movement'];}
if($creditTablesReady){$tx=$pdo->prepare("SELECT t.*,c.name category_name,a.name account_name,ci.name credit_card_name,ccp.invoice_id credit_invoice_id,ccp.id credit_purchase_id,ccpay.invoice_id card_payment_invoice_id FROM fin_transactions t LEFT JOIN fin_categories c ON c.id=t.category_id LEFT JOIN fin_accounts a ON a.id=t.account_id LEFT JOIN fin_credit_card_purchases ccp ON ccp.transaction_id=t.id AND ccp.user_id=t.user_id LEFT JOIN fin_credit_card_invoices cci ON cci.id=ccp.invoice_id AND cci.user_id=ccp.user_id LEFT JOIN fin_credit_cards ci ON ci.id=cci.card_id AND ci.user_id=cci.user_id LEFT JOIN fin_credit_card_payments ccpay ON ccpay.transaction_id=t.id AND ccpay.user_id=t.user_id WHERE t.user_id=? AND t.transaction_date BETWEEN ? AND ? ORDER BY t.transaction_date DESC,t.id DESC LIMIT 100");}
