$today=date('Y-m-d'); $isCurrentMonth=($month===date('Y-m')); $reservePercent=10.0; $financeTablesReady=true; $dueAlerts=[]; $recurringAlerts=[]; $cardInvoiceAlerts=[]; $cashForecast=null;
try {
 $pref=$pdo->prepare('SELECT reserve_percent FROM fin_user_finance_settings WHERE user_id=?'); $pref->execute([$uid]); $prefValue=$pref->fetchColumn(); if($prefValue!==false)$reservePercent=max(0,min(90,(float)$prefValue));
 $due=$pdo->prepare("SELECT t.id,t.kind,t.description,t.amount,COALESCE(t.due_date,t.transaction_date) due_on,a.name account_name FROM fin_transactions t LEFT JOIN fin_accounts a ON a.id=t.account_id WHERE t.user_id=? AND t.status='pending' AND COALESCE(t.due_date,t.transaction_date)<=DATE_ADD(CURDATE(),INTERVAL 2 DAY) ORDER BY due_on ASC,t.id ASC LIMIT 8"); $due->execute([$uid]); $dueAlerts=$due->fetchAll();
 $rec=$pdo->prepare("SELECT id,kind,description,amount,next_due_date,alert_days FROM fin_recurring_rules WHERE user_id=? AND is_active=1 AND next_due_date<=DATE_ADD(CURDATE(),INTERVAL alert_days DAY) ORDER BY next_due_date ASC LIMIT 8"); $rec->execute([$uid]); $recurringAlerts=$rec->fetchAll();
 if($isCurrentMonth){
  $paidIncomeQ=$pdo->prepare("SELECT COALESCE(SUM(amount),0) FROM fin_transactions WHERE user_id=? AND kind='income' AND status='paid' AND account_id IS NOT NULL AND transaction_date BETWEEN ? AND ? AND COALESCE(notes,'') NOT LIKE 'HP_TRANSFER:%'"); $paidIncomeQ->execute([$uid,$start,$end]); $paidIncome=(float)$paidIncomeQ->fetchColumn();
  $flowQ=$pdo->prepare("SELECT kind,COALESCE(SUM(amount),0) total FROM fin_transactions WHERE user_id=? AND status='pending' AND account_id IS NOT NULL AND COALESCE(due_date,transaction_date)<=? AND COALESCE(notes,'') NOT LIKE 'HP_TRANSFER:%' GROUP BY kind"); $flowQ->execute([$uid,$end]); $pendingFlow=['income'=>0.0,'expense'=>0.0]; foreach($flowQ as $flowRow)$pendingFlow[$flowRow['kind']]=(float)$flowRow['total'];
  $recQ=$pdo->prepare('SELECT kind,amount,frequency,interval_count,next_due_date,anchor_day,anchor_month FROM fin_recurring_rules WHERE user_id=? AND is_active=1 AND account_id IS NOT NULL AND next_due_date<=?'); $recQ->execute([$uid,$end]); $recRules=$recQ->fetchAll();
  $recurringFlow=['income'=>0.0,'expense'=>0.0];
  $advanceDate=static function($date,$frequency,$interval,$anchorDay,$anchorMonth){$current=new DateTimeImmutable($date);$interval=max(1,(int)$interval);if($frequency==='weekly')return $current->modify('+'.($interval*7).' days')->format('Y-m-d');if($frequency==='monthly'){$target=$current->modify('first day of this month')->modify('+'.$interval.' months');$day=min((int)$anchorDay,(int)$target->format('t'));return $target->setDate((int)$target->format('Y'),(int)$target->format('m'),$day)->format('Y-m-d');}$year=(int)$current->format('Y')+$interval;$monthNumber=(int)$anchorMonth;$first=$current->setDate($year,$monthNumber,1);$day=min((int)$anchorDay,(int)$first->format('t'));return $first->setDate($year,$monthNumber,$day)->format('Y-m-d');};
