  $incomeForecast=$paidIncome+$pendingFlow['income']+$recurringFlow['income'];
  $cardBillsDue=0.0; if($creditTablesReady){$billQ=$pdo->prepare("SELECT COALESCE(SUM(GREATEST(COALESCE(p.total,0)-COALESCE(py.paid,0),0)),0) FROM fin_credit_card_invoices i LEFT JOIN (SELECT cp.invoice_id,SUM(t.amount) total FROM fin_credit_card_purchases cp INNER JOIN fin_transactions t ON t.id=cp.transaction_id AND t.user_id=cp.user_id GROUP BY cp.invoice_id) p ON p.invoice_id=i.id LEFT JOIN (SELECT invoice_id,SUM(amount) paid FROM fin_credit_card_payments GROUP BY invoice_id) py ON py.invoice_id=i.id WHERE i.user_id=? AND i.due_date<=?");$billQ->execute([$uid,$end]);$cardBillsDue=(float)$billQ->fetchColumn();}
  $projectedEnd=(float)$allBalance+$pendingFlow['income']-$pendingFlow['expense']+$recurringFlow['income']-$recurringFlow['expense']-$cardBillsDue;
  $reserveTarget=$incomeForecast*$reservePercent/100;
  $cashForecast=['income'=>$incomeForecast,'end_balance'=>$projectedEnd,'reserve_target'=>$reserveTarget,'above_reserve'=>$projectedEnd-$reserveTarget,'breach'=>$projectedEnd<$reserveTarget];
