<script>
(()=>{const method=document.getElementById('payment_method'),cardRow=document.getElementById('credit-card-row'),cardSelect=document.getElementById('credit_card_id'),accountSelect=document.querySelector('select[name=account_id]'),statusSelect=document.querySelector('select[name=status]'),dueRow=document.getElementById('due-date-row'),dueInput=document.getElementById('due_date'),note=document.getElementById('credit-account-note'),hint=document.getElementById('card-cycle-hint'),dateInput=document.querySelector('input[name=transaction_date]');if(!method||!cardRow||!cardSelect)return;const dateWithDay=(year,month,day)=>{const d=new Date(year,month,0).getDate();return new Date(year,month-1,Math.min(day,d))};const key=d=>String(d.getFullYear()).padStart(4,'0')+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');const label=d=>new Intl.DateTimeFormat('pt-BR').format(d);const update=()=>{const using=method.value==='Crédito';cardRow.hidden=!using;dueRow.hidden=using;cardSelect.required=using;if(accountSelect){accountSelect.disabled=using;if(using)accountSelect.value=''}if(statusSelect){statusSelect.disabled=using;if(using)statusSelect.value='paid'}if(dueInput)dueInput.disabled=using;if(note)note.hidden=!using;const opt=cardSelect.selectedOptions[0];if(!using||!opt||!opt.value){if(hint)hint.textContent=using?'Selecione um cartão para calcular o ciclo e o vencimento.':'';return}const close=Number(opt.dataset.closing),due=Number(opt.dataset.due),parts=(dateInput.value||new Date().toISOString().slice(0,10)).split('-').map(Number);let y=parts[0],m=parts[1],purchase=dateInput.value;let closeDate=dateWithDay(y,m,close);if(purchase>key(closeDate)){m++;if(m>12){m=1;y++}}closeDate=dateWithDay(y,m,close);let dueYear=y,dueMonth=m,dueDate=dateWithDay(dueYear,dueMonth,due);if(key(dueDate)<=key(closeDate)){dueMonth++;if(dueMonth>12){dueMonth=1;dueYear++}dueDate=dateWithDay(dueYear,dueMonth,due)}if(hint)hint.textContent='Fecha em '+label(closeDate)+' · vence em '+label(dueDate)+' (estimativa). Compras no dia de fechamento entram neste ciclo.'};method.addEventListener('change',update);cardSelect.addEventListener('change',update);dateInput?.addEventListener('change',update);update()})();
</script>
<script>
(()=>{
 const sidebar=document.querySelector(".sidebar");
 const toggle=sidebar?.querySelector(".mobile-menu-toggle");
 const nav=sidebar?.querySelector("nav");
 if(!sidebar||!toggle||!nav)return;
 const closeMenu=()=>{sidebar.classList.remove("menu-open");toggle.setAttribute("aria-expanded","false")};
 toggle.addEventListener("click",()=>{const open=sidebar.classList.toggle("menu-open");toggle.setAttribute("aria-expanded",String(open))});
 nav.querySelectorAll("a").forEach(link=>link.addEventListener("click",closeMenu));
 document.addEventListener("keydown",event=>{if(event.key==="Escape")closeMenu()});
})();
</script>
<script>
(function(){var kindInputs=document.querySelectorAll('input[name="kind"]');var category=document.querySelector('select[name="category_id"]');if(!kindInputs.length||!category)return;function update(){var selected='expense';for(var i=0;i<kindInputs.length;i++)if(kindInputs[i].checked)selected=kindInputs[i].value;for(var j=0;j<category.options.length;j++){var option=category.options[j];if(!option.value)continue;var allowed=option.getAttribute('data-kind')==='both'||option.getAttribute('data-kind')===selected;option.hidden=!allowed;if(!allowed&&option.selected)category.value='';}}for(var k=0;k<kindInputs.length;k++)kindInputs[k].addEventListener('change',update);update();})();
</script>
</body></html>
